/// Matrix in compressed-column form.
/// The structure is used internally to store matrices in the triplet form as well,
/// but the API requires that the matrices are in the CSC format.
final class OSQPCscMatrix extends ffi.Struct {
  /// < number of rows
  @OSQPInt()
  external int m;

  /// < number of columns
  @OSQPInt()
  external int n;

  /// < column pointers (size n+1); col indices (size nzmax) starting from 0 for triplet format
  external ffi.Pointer<OSQPInt> p;

  /// < row indices, size nzmax starting from 0
  external ffi.Pointer<OSQPInt> i;

  /// < numerical values, size nzmax
  external ffi.Pointer<OSQPFloat> x;

  /// < maximum number of entries
  @OSQPInt()
  external int nzmax;

  /// < number of entries in triplet matrix, -1 for csc
  @OSQPInt()
  external int nz;

  /// < 1 if the p, i and x pointers were allocated automatically, 0 if they are owned by the user
  @OSQPInt()
  external int owned;

  static ffi.Pointer<OSQPCscMatrix> $allocate(
    ffi.Allocator $allocator, {
    required int m,
    required int n,
    required ffi.Pointer<OSQPInt> p,
    required ffi.Pointer<OSQPInt> i,
    required ffi.Pointer<OSQPFloat> x,
    required int nzmax,
    required int nz,
    required int owned,
  }) => $allocator<OSQPCscMatrix>()
    ..ref.m = m
    ..ref.n = n
    ..ref.p = p
    ..ref.i = i
    ..ref.x = x
    ..ref.nzmax = nzmax
    ..ref.nz = nz
