  set linsys_solver(osqp_linsys_solver_type value) =>
      linsys_solverAsInt = value.value;

  /// < boolean; allocate solution in OSQPSolver during osqp_setup
  @OSQPInt()
  external int allocate_solution;

  /// < boolean; write out progress
  @OSQPInt()
  external int verbose;

  /// < integer; level of detail for profiler annotations
  @OSQPInt()
  external int profiler_level;

  /// < boolean; warm start
  @OSQPInt()
  external int warm_starting;

  /// < data scaling iterations; if 0, then disabled
  @OSQPInt()
  external int scaling;

  /// < boolean; polish ADMM solution
  @OSQPInt()
  external int polishing;

  /// < ADMM penalty parameter
  @OSQPFloat()
  external double rho;

  /// < boolean; is rho scalar or vector?
  @OSQPInt()
  external int rho_is_vec;

  /// < ADMM penalty parameter
  @OSQPFloat()
  external double sigma;

  /// < ADMM relaxation parameter
  @OSQPFloat()
  external double alpha;

  /// < maximum number of CG iterations per solve
  @OSQPInt()
  external int cg_max_iter;

  /// < number of consecutive zero CG iterations before the tolerance gets halved
  @OSQPInt()
  external int cg_tol_reduction;

  /// < CG tolerance (fraction of ADMM residuals)
  @OSQPFloat()
  external double cg_tol_fraction;

  /// < Preconditioner to use in the CG method
  @ffi.UnsignedInt()
  external int cg_precondAsInt;

  osqp_precond_type get cg_precond =>
      osqp_precond_type.fromValue(cg_precondAsInt);
  set cg_precond(osqp_precond_type value) => cg_precondAsInt = value.value;

  /// rho stepsize adaption method
  @OSQPInt()
  external int adaptive_rho;

  /// Interval between rho adaptations
  ///
  /// When adaptive_rho == OSQP_ADAPTIVE_RHO_UPDATE_ITERATIONS, this is the number of iterations
  /// between rho updates.
  ///
  /// Not used when adaptive_rho is any other value.
  @OSQPInt()
  external int adaptive_rho_interval;

  /// Adaptation parameter controlling when non-fixed rho adaptations occur.
  ///
  /// - When adaptive_rho == OSQP_ADAPTIVE_RHO_UPDATE_TIME, this is the fraction of the
  /// setup time to use as the rho adaptation interval.
  /// - When adaptive_rho == OSQP_ADAPTIVE_RHO_UPDATE_KKT_ERROR, this is the fraction of
  /// the previous KKT error to adapt rho at.
  /// - Not used for any other adaptive_rho value.
  @OSQPFloat()
  external double adaptive_rho_fraction;

  /// Tolerance applied when adapting rho.
  ///
  /// New rho must be X times larger or smaller than the current one to change it
  @OSQPFloat()
  external double adaptive_rho_tolerance;

  /// < maximum number of iterations
  @OSQPInt()
  external int max_iter;

  /// < absolute solution tolerance
  @OSQPFloat()
  external double eps_abs;

  /// < relative solution tolerance
  @OSQPFloat()
  external double eps_rel;

  /// < primal infeasibility tolerance
  @OSQPFloat()
  external double eps_prim_inf;

  /// < dual infeasibility tolerance
  @OSQPFloat()
  external double eps_dual_inf;

  /// < boolean; use scaled termination criteria
  @OSQPInt()
  external int scaled_termination;

  /// < integer, check termination interval; if 0, checking is disabled
  @OSQPInt()
  external int check_termination;

  /// < Boolean; use duality gap termination criteria
  @OSQPInt()
  external int check_dualgap;

  /// < maximum time to solve the problem (seconds)
  @OSQPFloat()
  external double time_limit;

  /// < regularization parameter for polishing
  @OSQPFloat()
  external double delta;

  /// < number of iterative refinement steps in polishing
  @OSQPInt()
  external int polish_refine_iter;

  static ffi.Pointer<OSQPSettings> $allocate(
    ffi.Allocator $allocator, {
    required int device,
    required osqp_linsys_solver_type linsys_solver,
    required int allocate_solution,
    required int verbose,
    required int profiler_level,
    required int warm_starting,
    required int scaling,
    required int polishing,
    required double rho,
    required int rho_is_vec,
    required double sigma,
    required double alpha,
    required int cg_max_iter,
    required int cg_tol_reduction,
    required double cg_tol_fraction,
    required osqp_precond_type cg_precond,
    required int adaptive_rho,
    required int adaptive_rho_interval,
    required double adaptive_rho_fraction,
    required double adaptive_rho_tolerance,
    required int max_iter,
    required double eps_abs,
    required double eps_rel,
    required double eps_prim_inf,
    required double eps_dual_inf,
    required int scaled_termination,
    required int check_termination,
    required int check_dualgap,
    required double time_limit,
    required double delta,
    required int polish_refine_iter,
  }) => $allocator<OSQPSettings>()
    ..ref.device = device
    ..ref.linsys_solver = linsys_solver
    ..ref.allocate_solution = allocate_solution
    ..ref.verbose = verbose
    ..ref.profiler_level = profiler_level
    ..ref.warm_starting = warm_starting
    ..ref.scaling = scaling
    ..ref.polishing = polishing
    ..ref.rho = rho
    ..ref.rho_is_vec = rho_is_vec
    ..ref.sigma = sigma
    ..ref.alpha = alpha
    ..ref.cg_max_iter = cg_max_iter
    ..ref.cg_tol_reduction = cg_tol_reduction
    ..ref.cg_tol_fraction = cg_tol_fraction
    ..ref.cg_precond = cg_precond
    ..ref.adaptive_rho = adaptive_rho
    ..ref.adaptive_rho_interval = adaptive_rho_interval
    ..ref.adaptive_rho_fraction = adaptive_rho_fraction
    ..ref.adaptive_rho_tolerance = adaptive_rho_tolerance
    ..ref.max_iter = max_iter
    ..ref.eps_abs = eps_abs
    ..ref.eps_rel = eps_rel
    ..ref.eps_prim_inf = eps_prim_inf
    ..ref.eps_dual_inf = eps_dual_inf
    ..ref.scaled_termination = scaled_termination
    ..ref.check_termination = check_termination
    ..ref.check_dualgap = check_dualgap
    ..ref.time_limit = time_limit
    ..ref.delta = delta
    ..ref.polish_refine_iter = polish_refine_iter;
}

/// Structure to hold the computed solution (if any), and any certificates of
/// infeasibility (if any) found by the solver.
final class OSQPSolution extends ffi.Struct {
  /// < Primal solution
  external ffi.Pointer<OSQPFloat> x;

  /// < Lagrange multiplier associated with \f$l \le Ax \le u\f$
  external ffi.Pointer<OSQPFloat> y;

  /// < Primal infeasibility certificate
  external ffi.Pointer<OSQPFloat> prim_inf_cert;

  /// < Dual infeasibility certificate
  external ffi.Pointer<OSQPFloat> dual_inf_cert;

  static ffi.Pointer<OSQPSolution> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<OSQPFloat> x,
    required ffi.Pointer<OSQPFloat> y,
    required ffi.Pointer<OSQPFloat> prim_inf_cert,
    required ffi.Pointer<OSQPFloat> dual_inf_cert,
  }) => $allocator<OSQPSolution>()
    ..ref.x = x
    ..ref.y = y
    ..ref.prim_inf_cert = prim_inf_cert
    ..ref.dual_inf_cert = dual_inf_cert;
}

/// Main OSQP solver structure that holds all information.
final class OSQPSolver extends ffi.Struct {
  /// < Problem settings
  external ffi.Pointer<OSQPSettings> settings;

  /// < Computed solution
  external ffi.Pointer<OSQPSolution> solution;

  /// < Solver information
  external ffi.Pointer<OSQPInfo> info;

  /// < Internal solver workspace (contents not public)
  external ffi.Pointer<OSQPWorkspace> work;

  static ffi.Pointer<OSQPSolver> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<OSQPSettings> settings,
    required ffi.Pointer<OSQPSolution> solution,
    required ffi.Pointer<OSQPInfo> info,
    required ffi.Pointer<OSQPWorkspace> work,
  }) => $allocator<OSQPSolver>()
    ..ref.settings = settings
    ..ref.solution = solution
    ..ref.info = info
    ..ref.work = work;
}

typedef OSQPWorkspace = OSQPWorkspace_;

final class OSQPWorkspace_ extends ffi.Opaque {}

