/// Solver capabilities *
/// /
/// /**
/// Flags used to represent what capabilities the compiled OSQP solver has.
///
/// These flags are used as bit flags, so capabilities can be tested using bit-wise operations.
enum osqp_capabilities_type {
  /// << A direct linear solver is present in the algebra.
  OSQP_CAPABILITY_DIRECT_SOLVER(1),

  /// << An indirect linear solver is present in the algebra.
  OSQP_CAPABILITY_INDIRECT_SOLVER(2),

  /// << Code generation is present.
  OSQP_CAPABILITY_CODEGEN(4),

  /// << The problem matrices can be updated.
  OSQP_CAPABILITY_UPDATE_MATRICES(8),

  /// << Solution derivatives w.r.t P/q/A/l/u are available.
  OSQP_CAPABILITY_DERIVATIVES(16);

  final int value;
  const osqp_capabilities_type(this.value);

  static osqp_capabilities_type fromValue(int value) => switch (value) {
    1 => OSQP_CAPABILITY_DIRECT_SOLVER,
    2 => OSQP_CAPABILITY_INDIRECT_SOLVER,
    4 => OSQP_CAPABILITY_CODEGEN,
    8 => OSQP_CAPABILITY_UPDATE_MATRICES,
    16 => OSQP_CAPABILITY_DERIVATIVES,
    _ => throw ArgumentError(
      'Unknown value for osqp_capabilities_type: $value',
    ),
  };
}

/// Solver Errors  *
enum osqp_error_type {
  OSQP_NO_ERROR(0),
  OSQP_DATA_VALIDATION_ERROR(1),
  OSQP_SETTINGS_VALIDATION_ERROR(2),
  OSQP_LINSYS_SOLVER_INIT_ERROR(3),
  OSQP_NONCVX_ERROR(4),
  OSQP_MEM_ALLOC_ERROR(5),
  OSQP_WORKSPACE_NOT_INIT_ERROR(6),
  OSQP_ALGEBRA_LOAD_ERROR(7),
  OSQP_FOPEN_ERROR(8),
  OSQP_CODEGEN_DEFINES_ERROR(9),
  OSQP_DATA_NOT_INITIALIZED(10),

  /// < Function not implemented in this library
  OSQP_FUNC_NOT_IMPLEMENTED(11),
  OSQP_LAST_ERROR_PLACE(12);

  final int value;
  const osqp_error_type(this.value);

  static osqp_error_type fromValue(int value) => switch (value) {
    0 => OSQP_NO_ERROR,
    1 => OSQP_DATA_VALIDATION_ERROR,
    2 => OSQP_SETTINGS_VALIDATION_ERROR,
    3 => OSQP_LINSYS_SOLVER_INIT_ERROR,
    4 => OSQP_NONCVX_ERROR,
    5 => OSQP_MEM_ALLOC_ERROR,
    6 => OSQP_WORKSPACE_NOT_INIT_ERROR,
    7 => OSQP_ALGEBRA_LOAD_ERROR,
    8 => OSQP_FOPEN_ERROR,
    9 => OSQP_CODEGEN_DEFINES_ERROR,
    10 => OSQP_DATA_NOT_INITIALIZED,
    11 => OSQP_FUNC_NOT_IMPLEMENTED,
    12 => OSQP_LAST_ERROR_PLACE,
    _ => throw ArgumentError('Unknown value for osqp_error_type: $value'),
  };
}

/// Linear System Solvers *
enum osqp_linsys_solver_type {
  OSQP_UNKNOWN_SOLVER(0),
  OSQP_DIRECT_SOLVER(1),
  OSQP_INDIRECT_SOLVER(2);

  final int value;
  const osqp_linsys_solver_type(this.value);

  static osqp_linsys_solver_type fromValue(int value) => switch (value) {
    0 => OSQP_UNKNOWN_SOLVER,
    1 => OSQP_DIRECT_SOLVER,
    2 => OSQP_INDIRECT_SOLVER,
    _ => throw ArgumentError(
      'Unknown value for osqp_linsys_solver_type: $value',
    ),
  };
}

/// Polish Status  *
enum osqp_polish_status_type {
  OSQP_POLISH_LINSYS_ERROR(-2),
  OSQP_POLISH_FAILED(-1),
  OSQP_POLISH_NOT_PERFORMED(0),
  OSQP_POLISH_SUCCESS(1),
  OSQP_POLISH_NO_ACTIVE_SET_FOUND(2);

  final int value;
  const osqp_polish_status_type(this.value);

  static osqp_polish_status_type fromValue(int value) => switch (value) {
    -2 => OSQP_POLISH_LINSYS_ERROR,
    -1 => OSQP_POLISH_FAILED,
    0 => OSQP_POLISH_NOT_PERFORMED,
    1 => OSQP_POLISH_SUCCESS,
    2 => OSQP_POLISH_NO_ACTIVE_SET_FOUND,
    _ => throw ArgumentError(
      'Unknown value for osqp_polish_status_type: $value',
    ),
  };
}

/// Preconditioners for CG method *
enum osqp_precond_type {
  OSQP_NO_PRECONDITIONER(0),
  OSQP_DIAGONAL_PRECONDITIONER(1);

  final int value;
  const osqp_precond_type(this.value);

  static osqp_precond_type fromValue(int value) => switch (value) {
    0 => OSQP_NO_PRECONDITIONER,
    1 => OSQP_DIAGONAL_PRECONDITIONER,
    _ => throw ArgumentError('Unknown value for osqp_precond_type: $value'),
  };
}

/// Solver Status  *
enum osqp_status_type {
  OSQP_SOLVED(1),
  OSQP_SOLVED_INACCURATE(2),
  OSQP_PRIMAL_INFEASIBLE(3),
  OSQP_PRIMAL_INFEASIBLE_INACCURATE(4),
  OSQP_DUAL_INFEASIBLE(5),
  OSQP_DUAL_INFEASIBLE_INACCURATE(6),
  OSQP_MAX_ITER_REACHED(7),
  OSQP_TIME_LIMIT_REACHED(8),
  OSQP_NON_CVX(9),
  OSQP_SIGINT(10),
  OSQP_UNSOLVED(11);

  final int value;
  const osqp_status_type(this.value);

  static osqp_status_type fromValue(int value) => switch (value) {
    1 => OSQP_SOLVED,
    2 => OSQP_SOLVED_INACCURATE,
    3 => OSQP_PRIMAL_INFEASIBLE,
    4 => OSQP_PRIMAL_INFEASIBLE_INACCURATE,
    5 => OSQP_DUAL_INFEASIBLE,
    6 => OSQP_DUAL_INFEASIBLE_INACCURATE,
    7 => OSQP_MAX_ITER_REACHED,
    8 => OSQP_TIME_LIMIT_REACHED,
    9 => OSQP_NON_CVX,
    10 => OSQP_SIGINT,
    11 => OSQP_UNSOLVED,
    _ => throw ArgumentError('Unknown value for osqp_status_type: $value'),
  };
}
